/// <summary>
/// Environment-wide item snapshot settings - one row. ResyncRequestedUtc: "Ask all devices to full
/// re-sync"; every handheld whose last full download is older does one (via getAppControl).
/// </summary>
public class HSMobileOpsSkuSnapshotSetup extends common
{
}

Method.Source:
public static HSMobileOpsSkuSnapshotSetup find(boolean _forUpdate = false)
{
    HSMobileOpsSkuSnapshotSetup setup;

    setup.selectForUpdate(_forUpdate);
    select firstOnly setup;
    return setup;
}

/// <summary>
/// Asks every handheld for a full re-sync from now.
/// </summary>
public static utcdatetime requestResync()
{
    HSMobileOpsSkuSnapshotSetup setup;
    utcdatetime                 now = DateTimeUtil::utcNow();

    ttsbegin;
    select forUpdate firstOnly setup;
    setup.ResyncRequestedUtc = now;
    if (setup.RecId)
    {
        setup.update();
    }
    else
    {
        setup.insert();
    }
    ttscommit;
    return now;
}
